        { type: 'order', q: 'Дыхание квадратом: расставь шаги', items: ['Вдох на 4 счёта', 'Задержка на 4', 'Выдох на 4', 'Пауза на 4'], why: 'Повтори так 4–5 раз, и станет спокойнее.' },
        { type: 'one', q: 'Что помогает, когда грустно?', a: ['Поговорить с близким', 'Не спать всю ночь', 'Сидеть одному неделю', 'Ничего не есть'], c: 0, why: 'Разговор, сон и прогулка помогают справиться с грустью.' },
        { type: 'tf', q: 'Перепады настроения во время взросления — это нормально.', c: true, why: 'Гормоны влияют и на мозг, он учится управлять чувствами.' },
        { type: 'case', story: 'Уже три недели Оле почти каждый день грустно, ничего не радует, плохо спится.', q: 'Что ей сделать?', a: [{ t: 'Рассказать маме, папе или школьному психологу', ok: true, why: 'Долгая грусть — повод получить помощь.' }, { t: 'Позвонить на детский телефон доверия', ok: true, why: 'Там выслушают и помогут — бесплатно и анонимно.' }, { t: 'Терпеть и никому не говорить', ok: false, why: 'Одной справляться тяжело. Просить помощи — правильно.' }], why: 'Если плохо долго, нужно сказать взрослым.' },
        { type: 'sort', q: 'Как справиться со злостью?', groups: ['Помогает', 'Вредит'], items: [['Сделать паузу', 0], ['Подышать', 0], ['Побегать', 0], ['Сказать словами', 0], ['Ударить кого-то', 1], ['Кричать на всех', 1], ['Ломать чужие вещи', 1]], why: 'Злость можно выпустить, не раня других.' },
        { type: 'tf', q: 'Просить помощи — это признак слабости.', c: false, why: 'Просить помощи — смело и разумно.' }
